<?php require_once 'config/database.php';require_once 'includes/functions.php';require_login();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$st=$conn->prepare('SELECT COUNT(*) sales_count,COALESCE(SUM(total),0) revenue FROM sales WHERE DATE(sold_at) BETWEEN ? AND ?');$st->bind_param('ss',$from,$to);$st->execute();$summary=$st->get_result()->fetch_assoc();$st=$conn->prepare('SELECT si.product_name,SUM(si.quantity) quantity,SUM(si.subtotal) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE DATE(s.sold_at) BETWEEN ? AND ? GROUP BY si.product_name ORDER BY quantity DESC');$st->bind_param('ss',$from,$to);$st->execute();$items=$st->get_result();$pageTitle='Reports';$active='reports';require 'includes/header.php';?><div class="card"><div class="card-header"><h3 class="card-title">Sales Report</h3></div><div class="card-body"><form method="get" class="form-inline mb-4"><label class="mr-2">From</label><input type="date" name="from" class="form-control mr-3" value="<?=e($from)?>" required><label class="mr-2">To</label><input type="date" name="to" class="form-control mr-3" value="<?=e($to)?>" required><button class="btn btn-primary">Generate</button> <button type="button" class="btn btn-default ml-2" onclick="window.print()">Print</button></form><div class="row"><div class="col-md-4"><div class="info-box"><span class="info-box-icon bg-info"><i class="fas fa-receipt"></i></span><div class="info-box-content"><span class="info-box-text">Number of Sales</span><span class="info-box-number"><?=$summary['sales_count']?></span></div></div></div><div class="col-md-4"><div class="info-box"><span class="info-box-icon bg-success"><i class="fas fa-money-bill-wave"></i></span><div class="info-box-content"><span class="info-box-text">Total Revenue</span><span class="info-box-number"><?=money($summary['revenue'])?></span></div></div></div></div><h5>Products Sold</h5><table class="table table-bordered"><thead><tr><th>Product</th><th>Quantity Sold</th><th>Revenue</th></tr></thead><tbody><?php if(!$items->num_rows):?><tr><td colspan="3">No sales in this date range.</td></tr><?php else:while($r=$items->fetch_assoc()):?><tr><td><?=e($r['product_name'])?></td><td><?=$r['quantity']?></td><td><?=money($r['revenue'])?></td></tr><?php endwhile;endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
